<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $kind
 * @property string $label
 * @property string $currency
 * @property string|null $country_code
 * @property string|null $last4
 * @property string|null $bank_code
 * @property string|null $bank_name
 * @property string|null $account_name
 * @property string|null $account_number
 * @property string|null $provider
 * @property string|null $provider_recipient_code
 * @property bool $is_default
 * @property Carbon|null $verified_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 * @property Carbon|null $deleted_at
 */
/* @properties-end */
class PayoutMethod extends Model
{
    use HasPrefixedId, SoftDeletes;

    protected static string $idPrefix = 'pm';

    protected $fillable = [
        'user_id', 'kind', 'label', 'currency', 'country_code', 'last4', 'bank_code', 'bank_name', 'account_name',
        'account_number', 'provider', 'provider_recipient_code', 'is_default', 'verified_at',
    ];

    protected $hidden = ['account_number', 'provider_recipient_code', 'account_name'];

    protected function casts(): array
    {
        return [
            'account_name' => 'encrypted',
            'account_number' => 'encrypted',
            'provider_recipient_code' => 'encrypted',
            'is_default' => 'boolean',
            'verified_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }
}
